
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_c_m11_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_c_m11", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-2.056449154044882e-01, -2.155455072636588e-01, -2.281655247735487e-01, -2.418268567161022e-01, -2.497330556572428e-01, -2.342319705574749e-01, -1.689793176733561e-01, -7.242546774711016e-02, -5.235371968626182e-02, 2.665905395057006e-02, 2.873676705474401e-02, -2.340039266167543e-02, -4.878829133317207e-02, -3.755521479535216e-02, -8.724471685912130e-03, 7.274043776605146e-03, -4.334797748305332e-02, -6.054253714740705e-02, -1.942631658199280e-02, -2.785326966351949e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


